const ring = backends
  .filter((b) => b.healthy)
  .flatMap((b) => Array.from({ length: REPLICAS }, (_, i) => ({ at: hash32(`${b.id}#${i}`), id: b.id })))
  .sort((x, y) => x.at - y.at || (x.id < y.id ? -1 : x.id > y.id ? 1 : 0));
return keys.map((key) => {
  const h = hash32(key);
  return (ring.find(entry => entry.at >= h)?.id ?? ring[0]?.id ?? null);
});
